"""Data Transfer Objects for Rule-Based Activity Monitoring and AI Flag Explanations."""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime
from typing import Any, Optional


@dataclass(frozen=True)
class ActivityFlagDTO:
    """Security/compliance alert generated by deterministic rules engine for teller review."""

    flag_code: str  # "LARGE_TRANSACTION", "RAPID_WITHDRAWALS", "DORMANT_ACCOUNT_SPIKE"
    severity: str   # "LOW", "MEDIUM", "HIGH"
    rule_name: str
    triggered_at: datetime
    description: str
    metrics: dict[str, Any] = field(default_factory=dict)
    account_number_masked: str = ""
    ai_explanation: Optional[str] = None

    def with_explanation(self, explanation: str) -> ActivityFlagDTO:
        """Return a copy of this flag with an AI or deterministic narrative explanation attached."""
        return ActivityFlagDTO(
            flag_code=self.flag_code,
            severity=self.severity,
            rule_name=self.rule_name,
            triggered_at=self.triggered_at,
            description=self.description,
            metrics=self.metrics,
            account_number_masked=self.account_number_masked,
            ai_explanation=explanation,
        )

